window.ScripturaLexicons.BDAG_PART_0275 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-01\" data-source=\"BDAG\" data-search=\"παρηγορία, ας, ἡ substantivo feminino encorajamento; consolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρηγορία, ας, ἡ</td><td>substantivo feminino</td><td>encorajamento; consolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-02\" data-source=\"BDAG\" data-search=\"παρθενία, ας, ἡ substantivo feminino virgindade; condição virginal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρθενία, ας, ἡ</td><td>substantivo feminino</td><td>virgindade; condição virginal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-03\" data-source=\"BDAG\" data-search=\"παρθένος, ου, ἡ substantivo feminino e masculino virgem; pessoa casta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρθένος, ου, ἡ</td><td>substantivo feminino e masculino</td><td>virgem; pessoa casta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-04\" data-source=\"BDAG\" data-search=\"Πάρθοι, ων, οἱ substantivo masculino plural; gentílico partos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πάρθοι, ων, οἱ</td><td>substantivo masculino plural; gentílico</td><td>partos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-05\" data-source=\"BDAG\" data-search=\"παρίημι verbo negligenciar; enfraquecer; tornar-se indolente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρίημι</td><td>verbo</td><td>negligenciar; enfraquecer; tornar-se indolente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-06\" data-source=\"BDAG\" data-search=\"παριστάνω remissão verbal ver παρίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παριστάνω</td><td>remissão verbal</td><td>ver παρίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-07\" data-source=\"BDAG\" data-search=\"παρίστημι verbo transitivo e intransitivo apresentar; oferecer; estar presente; auxiliar; demonstrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρίστημι</td><td>verbo transitivo e intransitivo</td><td>apresentar; oferecer; estar presente; auxiliar; demonstrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-08\" data-source=\"BDAG\" data-search=\"Παρμενᾶς, ᾶ, ὁ nome próprio masculino Pármenas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Παρμενᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Pármenas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-09\" data-source=\"BDAG\" data-search=\"παροδεύω verbo passar por; seguir caminho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροδεύω</td><td>verbo</td><td>passar por; seguir caminho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-10\" data-source=\"BDAG\" data-search=\"παρόδιος, ον adjetivo substantivado viajante de passagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρόδιος, ον</td><td>adjetivo substantivado</td><td>viajante de passagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-11\" data-source=\"BDAG\" data-search=\"πάροδος, ου, ἡ substantivo feminino passagem; caminho; visita de passagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάροδος, ου, ἡ</td><td>substantivo feminino</td><td>passagem; caminho; visita de passagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-12\" data-source=\"BDAG\" data-search=\"παροικέω verbo morar próximo; residir como estrangeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροικέω</td><td>verbo</td><td>morar próximo; residir como estrangeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-13\" data-source=\"BDAG\" data-search=\"παροικία, ας, ἡ substantivo feminino residência no estrangeiro; comunidade; paróquia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροικία, ας, ἡ</td><td>substantivo feminino</td><td>residência no estrangeiro; comunidade; paróquia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-14\" data-source=\"BDAG\" data-search=\"πάροικος, ον adjetivo e substantivo masculino estrangeiro residente; peregrino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάροικος, ον</td><td>adjetivo e substantivo masculino</td><td>estrangeiro residente; peregrino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-15\" data-source=\"BDAG\" data-search=\"παροιμία, ας, ἡ substantivo feminino provérbio; máxima; linguagem figurada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροιμία, ας, ἡ</td><td>substantivo feminino</td><td>provérbio; máxima; linguagem figurada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-16\" data-source=\"BDAG\" data-search=\"πάροινος, ον adjetivo dado ao vinho; ébrio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάροινος, ον</td><td>adjetivo</td><td>dado ao vinho; ébrio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-17\" data-source=\"BDAG\" data-search=\"παροίχομαι verbo médio depoente ter passado; haver transcorrido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροίχομαι</td><td>verbo médio depoente</td><td>ter passado; haver transcorrido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-18\" data-source=\"BDAG\" data-search=\"παρομοιάζω verbo assemelhar-se; ser muito parecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρομοιάζω</td><td>verbo</td><td>assemelhar-se; ser muito parecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-19\" data-source=\"BDAG\" data-search=\"παρόμοιος, (α), ον adjetivo semelhante; parecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρόμοιος, (α), ον</td><td>adjetivo</td><td>semelhante; parecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0275-20\" data-source=\"BDAG\" data-search=\"παρόν, τό remissão substantivada ver πάρειμι 1b BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρόν, τό</td><td>remissão substantivada</td><td>ver πάρειμι 1b</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0275-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρηγορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρηγορία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρηγορέω</span> «exortar, consolar»; Aeschyl. e outros; 4 Macc 5:12; 6:1), fonte de encorajamento, consolo (Aeschyl., Ag. 95; Plut., Per. 170 [34, 3], Mor. 599b; Vett. Val. 183, 9f; 209, 25; Philo, Deus Imm. 65, Somn. 1, 112; Jos., Ant. 4, 195; Kaibel 204, 12 [I a.C.]); a respeito de pessoas, <span class=\"greek\">ἐγενήθησάν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">παρηγορία</span> «tornaram-se um consolo para mim» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a>.—DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρθενία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρθενία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρθένος</span>; Sappho, Pind., trágicos e outros), condição de ser virgem, virgindade (Callim., Hymn. 3, 6, acerca de Ártemis: <span class=\"greek\">παρθενίη</span> <span class=\"greek\">αἰώνιος</span>; Aristocritus [III a.C.]: 493 Fgm. 5 Jac., acerca de Héstia; Diod S 5, 3, 4) <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">Μαρίας</span> «a virgindade de Maria» IEph 19:1. Acerca do período de virgindade (com ênfase no momento em que se ingressa no estado matrimonial), <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῆς</span> «desde a sua virgindade» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:36</a> (<span class=\"greek\">ἀπό</span> 2b<span class=\"greek\">α</span>. Também <span class=\"greek\">ἐκ</span> <span class=\"greek\">παρθενίας</span> em Chariton 3, 7, 5; cf. cum quo vixit ab virginitate sua ad finem vitae suae = «com quem viveu desde sua virgindade até o fim da vida» CIL 10, 3720). Veja <span class=\"greek\">εὐνοῦχος</span>.—DELG s.v. <span class=\"greek\">παρθένος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρθένος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino e masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρθένος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior; Hom. e outros, em geral acerca de uma jovem em idade de casar, com ou sem ênfase na virgindade; veja especialmente PKöln VI, 245, 12 e ASP 31, ’91 p. 39) e <span class=\"greek\">ὁ</span> (veja as referências em b); em nossa literatura, pessoa que nunca manteve relações sexuais, virgem, pessoa casta.<br><br>ⓐ Mulher em idade de casar, com ênfase na virgindade, <span class=\"greek\">ἡ</span> <span class=\"greek\">παρθένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a>, 7, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:25</a> (FStrobel, NovT 2, ’58, 199–227), 28, 34; Pol 5:3; Hv 4, 2, 1; Hs 9, 1, 2; 9, 2, 3; 5; 9, 3, 2; 4f; 9, 4, 3; 5f; 8 e outros; AcPl Ox 6, 16 (cf. Aa I 241, 15); GJs 13:1. Conforme Is 7:14 (<span class=\"hebrew\" dir=\"rtl\">הָעַלְמָה</span> <span class=\"hebrew\" dir=\"rtl\">הָרָה</span>; sobre isso ASchulz, BZ 23, ’35, 229–41; WBrownlee, The Mng. of Qumran for the Bible, esp. Is, ’64, 274–81) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> (cf. Menand., Sicyonius 372f <span class=\"greek\">παρθένος</span> <span class=\"greek\">γ</span>’ <span class=\"greek\">ἔτι</span>, <span class=\"greek\">ἄπειρος</span> <span class=\"greek\">ἀνδρός</span>). Também a respeito de Maria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:27ab</a>; GJs 9:1; 10:1; 15:2; 16:1; 19:3; ISm 1:1 e provavelmente Dg 12:8 (a ideia de que o espírito de um deus poderia gerar um filho com uma mulher, especificamente uma virgem, não era estranha à religião egípcia: Plut. Numa 62 [4, 6], Mor. 718ab; Philo, Cher. 43–50 [a esse respeito ENorden, D. Geburt des Kindes 78–90; ELeach, Genesis as Myth, and Other Essays ’69, 85–112; RBrown, The Virginal Conception and Bodily Resurrection of Jesus ’73, 62, especialmente n. 104; idem, The Birth of the Messiah ’77, 522f, especialmente n. 17]. Veja ainda a bibliografia sobre <span class=\"greek\">Ἰωσήφ</span> 4 e OBardenhewer, Mariä Verkündigung 1905; EPetersen, Die wunderbare Geburt des Heilandes 1909; HUsener, Das Weihnachtsfest2 1911; ASteinmann, D. jungfräul. Geburt des Herrn3 1926, D. Jungfrauengeburt u. die vergl. Religionsgeschichte 1919; GBox, The Virgin Birth of Jesus 1916; OCrain, The Credibility of the Virgin Birth 1925; JMachen, The Virgin Birth of Christ2 ’32 [a respeito FKattenbusch, StKr 102, 1930, 454–74]; EWorcester, Studies in the Birth of Our Lord ’32; KSchmidt, D. jungfrl. Geb. J. Chr.: ThBl 14, ’35, 289–97; FSteinmetzer, Empfangen v. Hl. Geist ’38; RBratcher, Bible Translator 9, ’58, 98–125 [hebraico, LXX, Mateus]; TBoslooper, The Virg. Birth ’62; HvCampenhausen, D. Jungfrauengeburt in d. Theol. d. alten Kirche ’62; JMeier, A Marginal Jew I, ’91, 205–52 [bibliografia].—RCooke, Did Paul Know the Virg. Birth? 1927; PBotz, D. Jungfrausch. Mariens im NT u. in der nachap. Zeit, dissertação, Tüb. ’34; DEdwards, The Virg. Birth in History and Faith ’43.—Clemen2 114–21; ENorden, D. Geburt des Kindes2 ’31; MDibelius, Jungfrauensohn u. Krippenkind ’32; HMerklein, Studien zu Jesus und Paulus [WUNT 105] ’98; em geral, RBrown, The Birth of the Messiah ’77, 133–63, especialmente 147–49. Em contraposição à ênfase helenística de Dibelius, veja OMichel e OBetz, Beih., ZNW 26, ’60, 3–23, sobre paralelos em Qumran.). Acerca das filhas de Filipe, <span class=\"greek\">παρθένοι</span> <span class=\"greek\">προφητεύουσαι</span> «virgens que profetizavam» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:9</a>. Acerca de virgens admitidas ao ofício eclesiástico das «viúvas» ISm 13:1 (veja AJülicher, PM 22, 1918, 111f. Diferentemente LZscharnack, Der Dienst der Frau 1902, 105 ff).—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:36</a>–38, veja <span class=\"greek\">γαμίζω</span> 1, e ainda PKetter, Trierer Theol. Ztschr. 56, ’47, 175–82 (<span class=\"greek\">παρθ</span>. significa muitas vezes «filha [virgem]»: Apollon. Rhod. 3, 86 <span class=\"greek\">παρθ</span>. <span class=\"greek\">Αἰήτεω</span>, e o escólio respectivo apresenta esta observação: <span class=\"greek\">παρθένον</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυγατέρα</span>; Lycophron versos 1141, 1175; Diod S 8, 6, 2; 16, 55, 3; 20, 84, 3 [plural ao lado de <span class=\"greek\">υἱοί</span>]. Igualmente Theod. Prodr. 1, 293 H. <span class=\"greek\">τὴν</span> <span class=\"greek\">σὴν</span> <span class=\"greek\">παρθένον</span> = «tua filha virgem»; em 3, 332 <span class=\"greek\">τ</span>. <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">παρθένον</span> refere-se à «amada» de alguém; igualmente 6, 466, além do fato de que <span class=\"greek\">παρθ</span>. pode significar simplesmente «moça» [por exemplo, Paus. 8, 20, 4]). Nas lápides judaicas, «em idade de casar, mas ainda não casada» CIJ I, 117. RSeeboldt, Spiritual Marriage in the Early Church, CTM 30, ’59, 103–19; 176–86.—Em imagem figurada: a congregação de Corinto como <span class=\"greek\">παρθένος</span> <span class=\"greek\">ἁγνή</span> (<span class=\"greek\">ἁγνός</span> a), «virgem pura», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:2</a> (sobre o tema, veja FConybeare, Die jungfräul. Kirche u. die jungfräul. Mutter: ARW 8, 1905, 373ff; 9, 1906, 73ff; Cumont3 283, 33).—<span class=\"greek\">ἡ</span> <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">παρθένος</span> AcPl Ox 6, 15f (sobre Tecla; cf. Aa I 241, 15 <span class=\"greek\">ἡ</span> <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">αἰδὼς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρθένου</span>).<br><br>ⓑ Homem virgem, <span class=\"greek\">ὁ</span> <span class=\"greek\">παρθένος</span> «virgem, homem casto» (CIG IV, 8784b; JosAs 8:1 emprega <span class=\"greek\">π</span>. sobre José; Pel.-Leg. 27, 1 emprega-o acerca de Abel; Suda acerca de Abel e Melquisedeque; Nonnus acerca do apóstolo João, também chamado «virgo» nos prólogos monarquianos [Kl. T. 12 1908, p. 13, 13]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:4</a> (sobre sua relação temática com 1 En 15:2–7 e outros, veja DOlson, CBQ 59, ’97, 492–510).—JFord, The Mng. of ‘Virgin’, NTS 12, ’66, 293–99.—B. 90. New Docs 4, 224–27. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάρθοι, ων, οἱ</h1><div class=\"entry-meta\"><span>substantivo masculino plural; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πάρθοι</span>, <span class=\"greek\">ων</span>, <span class=\"greek\">οἱ</span> (desde Hdt 3, 93, 3; OGI 544, 32; índice de Joseph.; SibOr, índice de nomes), partos (sucessores dos persas; a Pártia situava-se a sudeste do mar Cáspio, mas nos tempos do NT seu império estendia-se até o Eufrates) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a> (Ps.-Callisth. 2, 4, 9 … <span class=\"greek\">Πάρθων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἐλυμαίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Βαβυλωνίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Μεσοποταμίαν</span> … <span class=\"greek\">χώραν</span>. Cf. 1, 2, 2 <span class=\"greek\">Σκύθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἄραβες</span> <span class=\"greek\">καὶ</span> … ; 14 nomes ao todo; acerca de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a>–11, veja SWeinstock, JRS 38, ’48, 43–46).—Bibliografia em Schürer I 351, 40; JBrinkman, CBQ 25, ’63, 418–27.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρίημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρίημι</span>, futuro <span class=\"greek\">παρήσω</span> LXX; infinitivo do 2.º aoristo <span class=\"greek\">παρεῖναι</span>; perfeito passivo <span class=\"greek\">παρεῖμαι</span> LXX; particípio passivo <span class=\"greek\">παρειμένος</span> (Hom.+).<br><br>① Deixar de fazer alguma coisa, negligenciar (Pind., Hdt. e outros; 4 Macc 5:29), <span class=\"greek\">τὶ</span> «algo» (Jos., Bell. 2, 202, Ant. 8, 218) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἔδει</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">κἀκεῖνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρεῖναι</span> «estas coisas era necessário fazer e aquelas não negligenciar» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:42</a> (variante textual <span class=\"greek\">ἀφεῖναι</span> e outras; cf. <span class=\"greek\">πάρεσις</span>).<br><br>② Estar fraco, deixar cair ao lado, afrouxar, enfraquecer; particípio perfeito passivo «enfraquecido, desanimado, caído» (Eur. e outros; Pla., Leg. 11, 931d; Diod S 14, 105, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">παρειμένοι</span>; Plut., Mor. 102a; LXX; TestJob 18:4 <span class=\"greek\">παρειμένη</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὀσφύας</span>; ApcMos 26 <span class=\"greek\">τοὺς</span> <span class=\"greek\">παρειμένους</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span>; Philo, in Flacc. 10 <span class=\"greek\">διανοίας</span> <span class=\"greek\">παρειμένης</span>; Jos., Ant. 6, 35) <span class=\"greek\">παρειμέναι</span> <span class=\"greek\">χεῖρες</span> «mãos enfraquecidas» (Sir 2:12; cf. Jos., Ant. 13, 343; Cornutus 16 p. 23, 18), com <span class=\"greek\">παραλελυμένα</span> <span class=\"greek\">γόνατα</span> «joelhos debilitados» (como Is 35:3; Sir 25:23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:12</a>.<br><br>③ Ser negligente no esforço, descuidado, indolente; particípio perfeito passivo com <span class=\"greek\">νωθρός</span> (como Sir 4:29) 1 Cl 34:1. (Com <span class=\"greek\">ἀργός</span>) <span class=\"greek\">π</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀγαθόν</span> «descuidado em toda boa obra» 34:4.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παριστάνω</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παριστάνω</span>: veja <span class=\"greek\">παρίστημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρίστημι</h1><div class=\"entry-meta\"><span>verbo transitivo e intransitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρίστημι</span>/<span class=\"greek\">παριστάνω</span> (a palavra desde Hom.+; a forma posterior <span class=\"greek\">παριστάνω</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:13</a>, 16; mas <span class=\"greek\">παρίστησι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:8</a>, variante textual; Ath. 33, 1], desde Polyb. e outros; Epict. 3, 22, 87; SIG 589, 46 [196 a.C.]; 814, 36 [67 d.C.]; 1109, 76.—B-D-F §93; Mlt-H. 202), infinitivo presente <span class=\"greek\">παραστᾶν</span> (Tat. 33, 1; Ath. 11, 3), particípio plural <span class=\"greek\">παριστῶντες</span> (Tat. 1, 3—B-D-F §93); futuro <span class=\"greek\">παραστήσω</span>; 1.º aoristo <span class=\"greek\">παρέστησα</span>; 2.º aoristo <span class=\"greek\">παρέστην</span>; perfeito <span class=\"greek\">παρέστηκα</span>, particípio <span class=\"greek\">παρεστηκώς</span> ou <span class=\"greek\">παρεστώς</span>; mais-que-perfeito <span class=\"greek\">παρειστήκειν</span>; infinitivo <span class=\"greek\">παρεστάναι</span> (Dt 18:5; PsSol 2:36). Médio: futuro <span class=\"greek\">παραστήσομαι</span>. Passivo: 1.º aoristo <span class=\"greek\">παρεστάθην</span>.<br><br>① Transitivo (presente, imperfeito, futuro, 1.º aoristo ativo), fazer estar presente de algum modo.<br><br>ⓐ Colocar ao lado, pôr à disposição de alguém, <span class=\"greek\">τινά</span> ou <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> «alguém ou alguma coisa para alguém» (Demetr.: 722 Fgm. 7 Jac.; Socrates of Rhodes [I a.C.]: 192 Fgm. 1 p. 927, 25 Jac. [em Athen. 4, 148b]; Lucian, D. Mar. 6, 2) <span class=\"greek\">παραστήσει</span> <span class=\"greek\">μοι</span> <span class=\"greek\">λεγιῶνας</span> «porá legiões à minha disposição» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a>. <span class=\"greek\">τὶ</span> «algo» (cf. 2 Macc 12:3, variante textual <span class=\"greek\">σκάφη</span>), <span class=\"greek\">κτήνη</span> «fornecer animais de montaria» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:24</a>. Para proteção, <span class=\"greek\">παρέστησεν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">υἱούς</span> <span class=\"greek\">αὐτοῦ</span> «colocou os seus filhos ao lado dela» = José confiou Maria aos cuidados dos filhos GJs 18:1. Aqui pertence <span class=\"greek\">παραστήσατε</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> «apresentai-vos a Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:13b</a>. Com dativo e duplo acusativo (do objeto e do predicativo), <span class=\"greek\">ᾧ</span> <span class=\"greek\">παριστάνετε</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">δούλους</span> (<span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπακοήν</span>) «a quem vos entregais como escravos (para lhe obedecer)» (com acusativo seguido de <span class=\"greek\">εἰς</span> = «para» ou «em favor de» [veja MTreu, Alkaios ’52, p. 12]) v. 16; <span class=\"greek\">μηδὲ</span> <span class=\"greek\">παριστάνετε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὅπλα</span> <span class=\"greek\">ἀδικίας</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁμαρτίᾳ</span> v. 13a; cf. v. 19ab.<br><br>ⓑ Apresentar, representar.<br><br><span class=\"greek\">α</span>. Literalmente, <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> «alguém a alguém»: <span class=\"greek\">παρέστησαν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span> <span class=\"greek\">αὐτῷ</span> «apresentaram Paulo a ele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:33</a>. <span class=\"greek\">παρθένον</span> <span class=\"greek\">ἁγνὴν</span> <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Χριστῷ</span> «apresentar a Cristo uma virgem pura» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:2</a>. Sobre a «apresentação» de Jesus no templo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:22</a> (Billerb. II 120–23. Cf. também Olympiodorus, Life of Plato, ed. AWestermann 1850 p. 1: acerca de Platão, a quem se atribuía origem transcendente, <span class=\"greek\">λαβόντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">γονεῖς</span> <span class=\"greek\">βρέφος</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">τεθείκασιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ὑμηττῷ</span> <span class=\"greek\">βουλόμενοι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">θεοῖς</span> … <span class=\"greek\">θῦσαι</span> = «seus pais o tomaram ainda bebê e o colocaram no Himeto com a intenção de sacrificar … às divindades daquele lugar»). Com dativo de pessoa, acusativo de objeto e acusativo predicativo, <span class=\"greek\">οἷς</span> <span class=\"greek\">παρέστησεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ζῶντα</span> «aos quais se apresentou vivo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>; sem dativo, subentendido pelo contexto, <span class=\"greek\">παρέστησεν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ζῶσαν</span> «apresentou-a viva» 9:41.<br><br><span class=\"greek\">β</span>. Figuradamente, <span class=\"greek\">παραστήσω</span> <span class=\"greek\">σε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">σου</span> «mostrar-te-ei a ti mesmo face a face» 1 Cl 35:10 (Ps 49:21).<br><br>ⓒ «Apresentar» torna-se quase equivalente a fazer, tornar (Plut., Mor. 676c [<span class=\"greek\">ἡ</span> <span class=\"greek\">πίσσα</span>] <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶνον</span> <span class=\"greek\">εὔποτον</span> <span class=\"greek\">παρίστησι</span>): <span class=\"greek\">ἵνα</span> <span class=\"greek\">παραστήσῃ</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> «para que (Cristo) torne a igreja gloriosa diante de si» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:27</a>. <span class=\"greek\">σπούδασον</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">δόκιμον</span> <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:15</a>. <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἁγίους</span> <span class=\"greek\">κατενώπιον</span> <span class=\"greek\">αὐτοῦ</span> «tornar-vos santos diante dele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:22</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">παραστήσωμεν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">τέλειον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> «para que tornemos toda pessoa perfeita em Cristo» v. 28.<br><br>ⓓ Como termo técnico da linguagem sacrificial, oferecer, trazer, apresentar (<span class=\"greek\">παριστάναι</span> <span class=\"greek\">θυσίαν</span>, <span class=\"greek\">θύματα</span> etc.: Epici p. 41, 49 B.=p. 19, 16 K.; Polyb. 16, 25, 7; Diod S 3, 72, 1; Lucian, Sacr. 13; Jos., Bell. 2, 89, Ant. 4, 113; SIG 589, 46 [196 a.C.]; 694, 49; 736, 70; OGI 456, 20; 764, 23; 38. A voz média também é empregada assim desde X., An. 6, 1, 22); figuradamente, <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ζῶσαν</span> «oferecer os corpos como sacrifício vivo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a>.<br><br>ⓔ Como termo técnico jurídico, apresentar perante (um juiz) (Sb 4512, 82 [II a.C.]; OGI 669, 49; BGU 163, 3; 341, 14; 747 II, 26; 759, 22; 1139, 18). Alguns prefeririam entender <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:8</a> neste sentido: <span class=\"greek\">βρῶμα</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">παραστήσει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> «o alimento não nos apresentará diante (do tribunal) de Deus». Igualmente, <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐγερεῖ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παραστήσει</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ὑμῖν</span> «ressuscitar-nos-á e nos apresentará, juntamente convosco, diante dele (= diante de seu tribunal)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:14</a>. Entretanto, o sentido forense não é certo em nenhuma dessas passagens, e o significado é provavelmente «apresentar diante de Deus = aproximar de Deus» (cf. Rtzst., ZNW 13, 1912, 19f).<br><br>ⓕ Provar, demonstrar (Lysias 12, 51; X., Oec. 13, 1; Epict. 2, 23, 47; 2, 26, 4; Jos., Ant. 4, 47, Vi. 27; PLips 64, 34): <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">παραστῆσαι</span> <span class=\"greek\">δύνανταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">νυνὶ</span> <span class=\"greek\">κατηγοροῦσίν</span> <span class=\"greek\">μου</span> «nem podem provar diante de ti as acusações que agora fazem contra mim» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:13</a>.—Sobre o 1.º aoristo passivo Hs 8, 4, 1, veja 2a<span class=\"greek\">γ</span>, final.<br><br>② Intransitivo (médio e perfeito, mais-que-perfeito, 2.º aoristo ativo, mas veja também a<span class=\"greek\">γ</span>, final), estar presente de algum modo, encontrar-se presente.<br><br>ⓐ Presente, futuro, aoristo (TestJos 2:6; 20:6; TestSol 6:1 e C 12:1; TestAbr A 20 p. 103, 19 [Stone p. 54]; ApcMos 35; Mel., P. 62, 450).<br><br><span class=\"greek\">α</span>. Aproximar-se, vir, <span class=\"greek\">τινί</span> «a alguém» (Philo, De Jos. 94) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:39</a>; 27:23 (Plut., Lysander 444 [20, 7] <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὕπνους</span> <span class=\"greek\">παραστῆναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἄμμωνα</span>).—Também como termo técnico jurídico, comparecer perante, apresentar-se diante de (veja 1e acima.—Chariton 6, 6, 4 <span class=\"greek\">παρέστην</span> <span class=\"greek\">δικαστηρίῳ</span>): <span class=\"greek\">Καίσαρί</span> <span class=\"greek\">σε</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">παραστῆναι</span> «deves comparecer perante o imperador» (como juiz) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:24</a>; cf. subscrição de 2 Ti. <span class=\"greek\">πάντες</span> <span class=\"greek\">παραστησόμεθα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (variante textual <span class=\"greek\">Χριστοῦ</span>) «todos compareceremos diante do tribunal de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:10</a>. <span class=\"greek\">πάντας</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">παραστῆναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> Pol 6:2.<br><br><span class=\"greek\">β</span>. Sobre a aparição com intenção hostil (Appian, Illyr. 17 §51), absolutamente, <span class=\"greek\">παρέστησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">βασιλεῖς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> «os reis da terra se levantaram» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:26</a> (Ps 2:2).<br><br><span class=\"greek\">γ</span>. Vir em auxílio de, ajudar, pôr-se ao lado de <span class=\"greek\">τινί</span> «alguém» (Hom. e outros; X., Cyr. 5, 3, 19 e outros; PKöln VI, 245, 22 <span class=\"greek\">σὺ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">θεὰ</span> <span class=\"greek\">παρίστασο</span> «e tu, deusa, permanece ao meu lado», com sugestão de relação entre Atena e Odisseu [para paralelos e bibliografia veja ‘Ptocheia’ ou ‘Odysseus in Disguise at Troy’ (=ASP 31), ed. MParca ’91, 59]; Mitt-Wilck. II/2, 372 VI, 7; 12; Jos., Bell. 2, 245; SibOr 8, 407) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριός</span> <span class=\"greek\">μοι</span> <span class=\"greek\">παρέστη</span> «o Senhor esteve ao meu lado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:17</a> (cf. PHerm 125b, 8 [III d.C.] <span class=\"greek\">θεὸς</span> <span class=\"greek\">παρίσταταί</span> <span class=\"greek\">σοι</span>; Jos., Ant. 1, 341; SibOr 3, 705).—O 1.º aoristo passivo <span class=\"greek\">παρεστάθην</span> <span class=\"greek\">αὐτῷ</span> Hs 8, 4, 1 é provavelmente empregado em sentido ativo: «coloquei-me ao lado dele (para estar pronto para servir)».<br><br>ⓑ Perfeito e mais-que-perfeito (En 14:22; PsSol 2:36; TestSol 14:2 e outros; TestAbr A 7 p. 84, 29 [Stone p. 16]; Just., D. 9, 1).<br><br><span class=\"greek\">α</span>. Acerca de seres pessoais, ficar (perto ou ao lado), estar presente, <span class=\"greek\">τινί</span> «com alguém» (LXX; TestJob 24:10; Jos., Bell. 2, 281) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:10</a>; 1 Cl 34:6 (Da 7:10 Theod.). <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> «estar diante de alguém» (1 Km 16:21; TestAbr A 7 p. 84, 29f [Stone p. 16]) <span class=\"greek\">οὗτος</span> <span class=\"greek\">παρέστηκεν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὑγιής</span> «este está são diante de vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10</a>.—Sobretudo no particípio, modificando um substantivo e seguido da indicação de lugar: <span class=\"greek\">ὁ</span> <span class=\"greek\">κεντυρίων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεστηκὼς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐναντίας</span> <span class=\"greek\">αὐτοῦ</span> «o centurião que estava diante dele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:39</a> (cf. 1 Macc 11:68 S). <span class=\"greek\">Γαβριὴλ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεστηκὼς</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> «Gabriel, que está diante de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:19</a> (cf. Jdth 4:14; Tob 12:15 S). Sem indicação de lugar (Diod S 17, 66, 7 <span class=\"greek\">παρεστὼς</span> <span class=\"greek\">Φιλώτας</span> = «Filotas, que estava perto»; Diog. L. 2, 102; Aberciusins. 17; EpArist 19), <span class=\"greek\">εἷς</span> <span class=\"greek\">παρεστηκὼς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπηρετῶν</span> «um dos servos que estava ali» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:22</a>. <span class=\"greek\">ἰδὼν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μαθητὴν</span> <span class=\"greek\">παρεστῶτα</span> «ao ver o discípulo em pé perto» 19:26. (<span class=\"greek\">ἄγγελοι</span>) <span class=\"greek\">λειτουργοῦσιν</span> <span class=\"greek\">παρεστῶτες</span> «(anjos) servem estando presentes» 1 Cl 34:5. <span class=\"greek\">παρεστὼς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> «o Senhor presente ao lado» MPol 2:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">παρεστῶτες</span> <span class=\"greek\">αὐτῷ</span> «aqueles que estavam perto dele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:2</a>.—Substantivado, <span class=\"greek\">οἱ</span> <span class=\"greek\">παρεστηκότες</span> (PPetr II, 4, 6, 13 [III a.C.]) ou <span class=\"greek\">οἱ</span> <span class=\"greek\">παρεστῶτες</span> (Diog. L. 9, 27) «os circunstantes, espectadores, presentes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:47</a>, 69f; 15:35 (variantes textuais <span class=\"greek\">παρεστώτων</span>, <span class=\"greek\">ἑστηκότων</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:4</a>; no v. 2, a leitura amplamente atestada acrescenta um dativo: <span class=\"greek\">τοῖς</span> <span class=\"greek\">παρεστῶσιν</span> <span class=\"greek\">αὐτῷ</span> (cf. POxy 1204, 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">παρεστώς</span> <span class=\"greek\">σοι</span>).<br><br><span class=\"greek\">β</span>. Acerca de um momento, estar aqui, ter chegado (Il. 16, 853; Demosth. 18, 90; 21, 101): <span class=\"greek\">παρέστηκεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θερισμός</span> «chegou o tempo da colheita» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:29</a>.<br><br><span class=\"greek\">γ</span>. Como termo técnico agrícola (cf. OGI 56, 68 <span class=\"greek\">ὅταν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρώϊμος</span> <span class=\"greek\">σπόρος</span> <span class=\"greek\">παραστῇ</span>; PLille 8, 5), algo como estar plenamente desenvolvido: <span class=\"greek\">σταφυλὴ</span> <span class=\"greek\">παρεστηκυῖα</span> «uva madura» (em contraste com <span class=\"greek\">ὄμφαξ</span>) 1 Cl 23:4=2 Cl 11:3 (citação de origem desconhecida).—M-M. DELG s.v. <span class=\"greek\">ἵημι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παρμενᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Παρμενᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span>, acusativo -<span class=\"greek\">ᾶν</span> (Sb 2489), Pármenas (forma abreviada de <span class=\"greek\">Παρμενίδης</span>, <span class=\"greek\">Παρμενίων</span>, <span class=\"greek\">Παρμενίοκος</span> etc.—B-D-F §125, 1; W-S. §16, 9; Rob. 173), um dos sete homens designados em Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροδεύω</span>, 1.º aoristo, 3.ª pessoa singular <span class=\"greek\">παρώδευσεν</span> Wsd 5:14; particípio <span class=\"greek\">παροδεύσας</span> (Theocr. 23, 47; Heraclit. Sto. 68, p. 88, 6; Plut., Mor. 973d; Lucian, Scyth. 10; OGI 544, 32; Kaibel 810, 11; PMich 149, 12; 21 [texto astrológico]; Wsd; Jos., Bell. 5, 426, Ant. 19, 331), ir além de um ponto de referência, passar, passar por; <span class=\"greek\">ἔγνων</span> <span class=\"greek\">παροδεύσαντάς</span> <span class=\"greek\">τινας</span> <span class=\"greek\">ἐκεῖθεν</span> «fiquei conhecendo certas pessoas que haviam passado por ali vindo daquele lugar» IEph 9:1. Substantivado (Anton. Lib. 23, 6), <span class=\"greek\">ὡς</span> <span class=\"greek\">παροδεύοντα</span> «como alguém de passagem» IRo 9:3.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M s.v. <span class=\"greek\">πάροδος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρόδιος, ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρόδιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πάροδος</span>; Hyperid., Fgm. 261; Plut., Mor. 521d e outros; PTebt 45, 22; 47, 14 [113 a.C.]), que se detém (em algum lugar) durante uma viagem; substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. «aquele que viaja de passagem» (de outro modo <span class=\"greek\">παροδίτης</span> ou <span class=\"greek\">πάροδος</span>.—Thackeray, The LXX and Jewish Worship 1921, 26–28) D 12:2.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M s.v. <span class=\"greek\">πάροδος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάροδος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάροδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior; Thu. e outros; inscrições, papiros, LXX; PsSol 11:5; EpArist; Philo, Praem. 112; Joseph.).<br><br>① Via para viajantes, passagem, caminho de trânsito (X., An. 4, 7, 4 e outros; Diod S 20, 23, 2; EpArist 118; Jos., Ant. 14, 46) <span class=\"greek\">πάροδός</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">τῶν</span> … «sois o caminho para aqueles …» IEph 12:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">πάροδος</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span> «o caminho para os anjos» Hv 2, 2, 7 (veja a nota de Joly); Hs 9, 25, 2.<br><br>② Ato de mover-se até um ponto de referência e prosseguir o caminho, mas com a possibilidade de uma parada, passagem por algum lugar, <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. (Thu. 1, 126, 11; Polyb. 5, 68, 8; Cicero, Ad Att. 5, 20, 2; Lucian, D. Deor. 24, 2; PSI 354, 8; PLond III, 1041, 2 [VII d.C.]; Jos., Ant. 14, 38), <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">τινα</span> «ver alguém de passagem» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:7</a>.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροικέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροικέω</span>, futuro <span class=\"greek\">παροικήσω</span> LXX; 1.º aoristo <span class=\"greek\">παρῴκησα</span>; perfeito, 3.ª pessoa do plural <span class=\"greek\">παρῳκήκασιν</span> Ex 6:4 (veja o verbete seguinte; Thu. e outros; inscrições, papiros, LXX; PsSol 17:28; Demetr.: 722 Fgm. 1, 19 Jac.; Philo; Jos., Ant. 1, 121).<br><br>① Morar ou residir próximo, viver nas proximidades, morar ao lado, com dativo (Thu. 1, 71, 2 <span class=\"greek\">πόλει</span> <span class=\"greek\">ὁμοίᾳ</span> <span class=\"greek\">παρακοῦντες</span> = «vizinhos que habitam cidade-Estado semelhante à vossa»; 3, 93, 2; Plut., Mor. 4a; Lucian, Catap. 16; Philo, Sacr. Abel. 44; OGI 666, 13 [I d.C.], perto das pirâmides). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>, <span class=\"greek\">σὺ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">παροικεῖς</span> <span class=\"greek\">Ἰερουσαλήμ</span> … ; o contexto sugere que a forma indeclinável <span class=\"greek\">Ἰερουσαλήμ</span> seja tomada como dativo: «és o único que mora perto de Jerusalém (que não sabe o que aconteceu ali nos últimos dias?)». Cleopas fala de modo algo sarcástico em narrativa destinada a transmitir ironia. Para opiniões diferentes, veja 2 e 3.<br><br>② Habitar em determinado lugar como estrangeiro, ser estrangeiro. Na LXX, principalmente acerca de estrangeiros que vivem num lugar sem possuir cidadania (também PSI 677, 2 [III a.C.]; Diod S 13, 47, 4; cf. SIG 709, 9; índice IPriene; veja Elliott, em 3 abaixo). Também acerca de pessoas que vivem como estrangeiros na terra, longe de sua pátria celeste (Philo, Cher. 120, Rer. Div. Her. 267 e outros):<br><br>ⓐ Em certo lugar, viver como estrangeiro, habitar (um lugar) como estrangeiro, com acusativo de lugar (Isocr. 4, 162; Gen 17:8; Ex 6:4) 1 Cl ins ab; MPol ins a.—Muitos entendem <span class=\"greek\">Ἰερουσαλήμ</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>, <span class=\"greek\">σὺ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">παροικεῖς</span> <span class=\"greek\">Ἰερουσαλήμ</span>, como acusativo e interpretam aproximadamente: «és o único recém-chegado a Jerusalém?». Mas veja 1 e 3.—Provavelmente a inscrição de Pol também pertence aqui, pois <span class=\"greek\">Φιλίπποις</span> certamente deve ser alterado para <span class=\"greek\">Φιλίππους</span> com Lghtf. e Bihlmeyer (<span class=\"greek\">π</span>. com dativo significa «morar ao lado, ser vizinho», veja 1), e a formulação equivale semanticamente a Eus., HE 4, 23, 5 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παροικούσῃ</span> <span class=\"greek\">Γόρτυναν</span> (veja <span class=\"greek\">παροικία</span> 2).<br><br>ⓑ No meio de outros, viver como estrangeiro, com <span class=\"greek\">ἐν</span> (Gen 20:1; 21:34; 26:3 e outros; Philo, Conf. Lingu. 78) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>, variante textual; MPol ins b. <span class=\"greek\">Χριστιανοὶ</span> <span class=\"greek\">παροικοῦσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φθαρτοῖς</span> «os cristãos residem entre coisas perecíveis» Dg 6:8.<br><br>ⓒ Migrar, com <span class=\"greek\">εἰς</span>, «para», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a>.<br><br>③ Também simplesmente habitar, morar, sem a conotação de ser estrangeiro (Ps.-Scylax, Peripl. §93, no início [ed. BFabricius 1878] <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Σύρτιδος</span>; Sus 28 LXX), talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>, mas (veja 1 e 2a acima).—Quanto à bibliografia, veja especialmente JHElliott, s.v. <span class=\"greek\">πάροικος</span> 2.—DELG s.v. <span class=\"greek\">οἶκος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροικία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροικία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παροικέω</span>; TestLevi 11:2; PdeLabriolle, Paroecia: RSR 18, 1928, 60–72).<br><br>① Estado de estar em localidade estrangeira sem cidadania, permanência no estrangeiro, estada; também em sentido figurado, o próprio país estrangeiro.<br><br>ⓐ Literalmente (2 Esdr 8:35; prólogo de Sir, ln. 34; 3 Macc 7:19), sobre a permanência dos israelitas no Egito (Wsd 19:10), <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παροικίᾳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">Αἰγύπτου</span> «durante a estada na terra do Egito» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:17</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">Βαβυλῶνος</span> Theoph. Ant. 3, 28 [p. 264, 9]).<br><br>ⓑ Figuradamente, acerca da vida terrena do cristão, distante da pátria celeste (Ps 118:54; 119:5; cf. <span class=\"greek\">παροικέω</span> 1) <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">χρόνος</span> «o tempo de vossa estada nesta terra estrangeira» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a>. <span class=\"greek\">καταλείπειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span> «abandonar a estada na terra estrangeira deste mundo» 2 Cl 5:1 (cf. CIG 9474; IG XIV, 531, 7 <span class=\"greek\">τούτου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παροικίαν</span>; Philo, Conf. Lingu. 80 <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">παροικία</span>).<br><br>② Grupo cultual (cristão) entendido como composto de estrangeiros, congregação, paróquia (a palavra deriva de <span class=\"greek\">π</span>.), na medida em que representa uma comunidade de tais «estrangeiros» (Eus., HE 4, 23, 5 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παροικούσῃ</span> <span class=\"greek\">Γόρτυναν</span> <span class=\"greek\">ἅμα</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">λοιπαῖς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Κρήτην</span> <span class=\"greek\">παροικίαις</span>; Irenaeus em Eus. 5, 24, 14; Apollonius em Eus. 5, 18, 9. <span class=\"greek\">παροικία</span> significa «comunidade de pessoas» em PsSol 17:17) MPol ins., veja <span class=\"greek\">παροικέω</span> 2a.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάροικος, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάροικος</span>, <span class=\"greek\">ον</span> (Aeschyl., Thu.+), referente a ser estrangeiro residente, estrangeiro; em nossa literatura, quase sempre substantivado: <span class=\"greek\">πάροικος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> «estrangeiro, alienígena, pessoa que vive em lugar que não é seu lar» (frequente nas inscrições [índices OGI e SIG; Dssm., NB 54=BS 227f]; LXX; PsSol 17:28; TestLevi 11:2; ApcSed 11:8 p. 134, 22 Ja.; Philo, Cher. 121; Jos., Ant. 8, 59).<br><br>① Literalmente, com o lugar indicado por <span class=\"greek\">ἐν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:6</a> (adjetivo, conforme Gen 15:13), 29 (cf. Ex 2:22 <span class=\"greek\">πάροικός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">ἀλλοτρίᾳ</span>).<br><br>② Figuradamente, sobre os cristãos, cuja verdadeira pátria está no céu, Dg 5:5. Com <span class=\"greek\">ξένοι</span> (combinação encontrada duas vezes em Diod S 20, 84, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:19</a>. Com <span class=\"greek\">παρεπίδημοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:11</a> (sobre o tema do estranhamento, cf. M. Ant. 2, 17. Diferentemente, JHElliott enfatiza a condição sociopolítica inferior dos destinatários: Home for the Homeless, ’81, 50, n. 10, com bibliografia sobre o verbo e seus cognatos).—KSchmidt, Israels Stellung zu d. Fremdlingen u. Beisassen usw.: Judaica 1, ’46, 269–96; RFeldmeier, Die Christen als Fremde ’92.—PGauthier, em RLonis, L’étranger dans le monde grec ’88, 23–46 [SEG XXXVIII nº 2032]. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροιμία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροιμία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (de <span class=\"greek\">παρ</span>’ <span class=\"greek\">οἶμον</span>? = «observação lateral» [veja Schwyzer II 498; Frisk s.v. «semanticamente obscuro»]).<br><br>① Dito conciso, provérbio, adágio, máxima (assim Aeschyl. e outros; Herodas 2, 61; Socrat., Ep. 36 <span class=\"greek\">παροιμίαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παραβολαί</span>; Sir 6:35; Philo, Abr. 235, Vi. Mos. 1, 156; 2, 29, Exsecr. 150) <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παροιμίας</span> (Lucian, Dial. Mort. 6, 2; 8, 1) «o que diz o provérbio» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:22</a>.—LBieler, Die Namen d. Sprichworts in den klass. Sprachen: RhM n.s. 85, ’36, 240–47; GDalman, Jesus (tradução inglesa) 1929, 223–36.<br><br>② Comunicação breve que contém verdades destinadas a iniciados, dito velado, linguagem figurada, na qual ideias especialmente elevadas ficam ocultas: no uso joanino (Suda: <span class=\"greek\">παροιμία</span> = <span class=\"greek\">λόγος</span> <span class=\"greek\">ἀπόκρυφος</span>; Sir 39:3 <span class=\"greek\">ἀπόκρυφα</span> <span class=\"greek\">παροιμιῶν</span> <span class=\"greek\">ἐκζητήσει</span>. Conforme 47:17, <span class=\"greek\">ἑρμηνεία</span> é complemento de <span class=\"greek\">παροιμίαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:6</a>; 16:25ab, 29.—JQuasten, CBQ 10, ’48, 8f.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάροινος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάροινος</span>, <span class=\"greek\">ον</span> (Lysias 4, 8; Menand., Peric. 1022 S. [444 Kö.]; Diog. L. 1, 92; Lucian, Tim. 55; a emenda de TestJud 14:4 Ch. baseia-se em compreensão equivocada da estrutura literária daquele livro; <span class=\"greek\">π</span>. refere-se a pessoas em todos estes exemplos), referente àquele que costuma beber vinho em excesso, dado ao vinho, bêbado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:3</a>; Tit 1:7.—DELG s.v. <span class=\"greek\">οἶνος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροίχομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροίχομαι</span>, particípio perfeito neutro <span class=\"greek\">παρῳχηκός</span> (Tat. 26, 1) e <span class=\"greek\">παρῳχημένος</span>, médio depoente, ter passado, acerca do tempo (<span class=\"greek\">οἴχομαι</span> «ir, vir»; Hom. e outros; Dionys. Hal. 11, 5 <span class=\"greek\">χρόνος</span>; SIG 885, 5 <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρῳχημένων</span> <span class=\"greek\">χρόνων</span>; CPR 10, 6; PRyl 153, 35; Jos., Ant. 8, 301) <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">παρῳχημέναις</span> <span class=\"greek\">γενεαῖς</span> «nas gerações passadas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:16</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρομοιάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρομοιάζω</span> (<span class=\"greek\">παρόμοιος</span>; somente escritores cristãos), ser bastante semelhante a, parecer-se com <span class=\"greek\">τινί</span> «algo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a> (variante textual <span class=\"greek\">ὁμοιάζετε</span>).—DELG s.v. <span class=\"greek\">ὁμός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρόμοιος, (α), ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρόμοιος</span>, (<span class=\"greek\">α</span>), <span class=\"greek\">ον</span> (veja <span class=\"greek\">παρομοιάζω</span>; Hdt. e outros; GrBar 4:6; Tat. 15, 2), relativo a ser bastante semelhante, parecido, semelhante: <span class=\"greek\">παρόμοια</span> <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ποιεῖτε</span> «fazeis muitas outras coisas semelhantes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:8</a>, variante textual, 13.—DELG s.v. <span class=\"greek\">ὁμός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0275-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρόν, τό</h1><div class=\"entry-meta\"><span>remissão substantivada</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρόν</span>, <span class=\"greek\">τό</span>: veja <span class=\"greek\">πάρειμι</span> 1b.</p></section></article>"};
